// Firmware configuration constants

/// Firmware compatibility gate for CRS headers.
/// Must match `[target].fw_compat_id` in TOML packed by `crs-pack`.
pub const FW_COMPAT_ID: u32 = 0x2026_0216;

// Flash layout constants are generated by `kb_firmware/build.rs` from the selected board variant.
// Source: `kb_firmware/boards/<board>/flash_layout.rs`.
// This keeps the firmware and any host flashing scripts in sync.
include!(concat!(env!("OUT_DIR"), "/flash_layout.rs"));
